/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 *
 * Optimizations in this version:
 *   - Hoist all scalar coefficient computations out of the time loop.
 *   - Split each ADI sweep into clearly separated phases:
 *       (boundary initialization) -> (forward sweep) -> (boundary) -> (backward sweep).
 *   - Interchange loops so that j (recurrence direction) is outer and i is inner.
 *     This preserves the j-recursions but makes the inner loop stride-1 in memory
 *     for u and v, improving cache locality and enabling vectorization along i.
 *   - Reuse the common denominator in the Thomas forward sweeps by computing its
 *     reciprocal once per (i,j) and using multiplications instead of two divisions.
 *   - Introduce local restrict-qualified pointers to help the compiler with
 *     alias analysis and enable more aggressive optimization.
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;

  /* Create local restrict-qualified aliases for better alias analysis.
     The POLYBENCH_2D parameters decay to pointers of type DATA_TYPE (*)[n];
     we do not change the actual storage layout, only give the compiler
     stronger guarantees that u, v, p, q do not alias each other. */
  DATA_TYPE (*restrict u_)[n] = u;
  DATA_TYPE (*restrict v_)[n] = v;
  DATA_TYPE (*restrict p_)[n] = p;
  DATA_TYPE (*restrict q_)[n] = q;

  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;
  /* Precomputed coefficients used inside the sweeps:
     alpha_col = 1 + 2*d, alpha_row = 1 + 2*a. */
  DATA_TYPE alpha_col, alpha_row;

#pragma scop

  /* Coefficient setup: identical algebraically to the original code,
     but computed once, outside the time loop. */
  DX = SCALAR_VAL(1.0) / (DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0) / (DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0) / (DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0) + mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0) + mul2;
  f = d;

  alpha_col = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d;
  alpha_row = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a;

  for (t = 1; t <= _PB_TSTEPS; t++) {

    /* ============================================================
       Column sweep: implicit solve along j for each column index i.
       We reorganize this sweep into four phases:
         1) boundary/init
         2) forward sweep in j
         3) opposite boundary
         4) backward sweep in j
       The recurrence is along j only, so we can safely loop over i
       inside each fixed j without changing per-(i,j) dependencies.
       ============================================================ */

    /* 1) Column boundary conditions and forward-sweep seeds. */
    for (i = 1; i < _PB_N - 1; i++) {
      v_[0][i] = SCALAR_VAL(1.0);
      p_[i][0] = SCALAR_VAL(0.0);
      /* q_[i][0] = v_[0][i] = 1.0; we use the explicit value. */
      q_[i][0] = SCALAR_VAL(1.0);
    }

    /* 2) Forward sweep in j using Thomas algorithm.
       j is the recurrence dimension and must remain sequential.
       For each fixed j, all i-iterations are independent and
       access u_[j][i-1..i+1] contiguously in memory. */
    for (j = 1; j < _PB_N - 1; j++) {
      for (i = 1; i < _PB_N - 1; i++) {
        /* Common denominator for p and q; compute its reciprocal once. */
        DATA_TYPE denom_col = a * p_[i][j-1] + b;
        DATA_TYPE inv_denom_col = SCALAR_VAL(1.0) / denom_col;

        p_[i][j] = -c * inv_denom_col;

        q_[i][j] =
          ( -d * u_[j][i-1]
            + alpha_col * u_[j][i]
            - f * u_[j][i+1]
            - a * q_[i][j-1]
          ) * inv_denom_col;
      }
    }

    /* 3) Column sweep opposite boundary. */
    for (i = 1; i < _PB_N - 1; i++) {
      v_[_PB_N-1][i] = SCALAR_VAL(1.0);
    }

    /* 4) Backward substitution in j.
       Original code: for each i, j = N-2 .. 1:
         v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
       Here we express the same loop with a helper index jb that
       increases from 1 to N-2 while the physical j index decreases
       from N-2 down to 1. This preserves the recurrence order but
       allows i to be the inner, contiguous loop. */
    for (int jb = 1; jb < _PB_N - 1; jb++) {
      int j_idx = _PB_N - 1 - jb; /* j_idx: N-2, N-3, ..., 1 */
      for (i = 1; i < _PB_N - 1; i++) {
        v_[j_idx][i] = p_[i][j_idx] * v_[j_idx+1][i] + q_[i][j_idx];
      }
    }

    /* ============================================================
       Row sweep: implicit solve along j for each row index i.
       The structure is analogous to the column sweep, but now we
       use v as input and write back into u.
       ============================================================ */

    /* 1) Row boundary conditions and forward-sweep seeds. */
    for (i = 1; i < _PB_N - 1; i++) {
      u_[i][0] = SCALAR_VAL(1.0);
      p_[i][0] = SCALAR_VAL(0.0);
      /* q_[i][0] = u_[i][0] = 1.0; again use the explicit value. */
      q_[i][0] = SCALAR_VAL(1.0);
    }

    /* 2) Forward sweep in j for rows.
       As in the column sweep, j carries the recurrence and must be
       sequential; i is independent and used as the inner loop. */
    for (j = 1; j < _PB_N - 1; j++) {
      for (i = 1; i < _PB_N - 1; i++) {
        DATA_TYPE denom_row = d * p_[i][j-1] + e;
        DATA_TYPE inv_denom_row = SCALAR_VAL(1.0) / denom_row;

        p_[i][j] = -f * inv_denom_row;

        q_[i][j] =
          ( -a * v_[i-1][j]
            + alpha_row * v_[i][j]
            - c * v_[i+1][j]
            - d * q_[i][j-1]
          ) * inv_denom_row;
      }
    }

    /* 3) Row sweep opposite boundary. */
    for (i = 1; i < _PB_N - 1; i++) {
      u_[i][_PB_N-1] = SCALAR_VAL(1.0);
    }

    /* 4) Backward substitution in j for rows.
       Original code: for each i, j = N-2 .. 1:
         u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
       Again we employ jb as an increasing helper index. */
    for (int jb = 1; jb < _PB_N - 1; jb++) {
      int j_idx = _PB_N - 1 - jb; /* j_idx: N-2, N-3, ..., 1 */
      for (i = 1; i < _PB_N - 1; i++) {
        u_[i][j_idx] = p_[i][j_idx] * u_[i][j_idx+1] + q_[i][j_idx];
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n,
              POLYBENCH_ARRAY(u),
              POLYBENCH_ARRAY(v),
              POLYBENCH_ARRAY(p),
              POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

