  for (t = 1; t <= _PB_TSTEPS; t++) {

    /* ============================================================
       Column sweep
       ------------------------------------------------------------
       Original structure (per time step):

         for (i = 1; i < N-1; i++) {
           v[0][i] = 1; p[i][0] = 0; q[i][0] = 1;
           for (j = 1; j < N-1; j++) { ... }
           v[N-1][i] = 1;
           for (j = N-2; j >= 1; j--) { ... }
         }

       The recurrences are along j; different i are independent.
       To improve data locality for u and v (stored row-major), we
       reorganize the computation so that, in the sweeps, j is the
       outer loop and i is the inner loop. For this sweep we treat
       p and q as logically transposed and index them as p_[j][i]
       and q_[j][i]. This way, accesses to u, v, p, and q in the
       innermost loops are all over the contiguous i-dimension.

       Note: p and q are scratch arrays that are fully recomputed
       in each sweep; no information from their layout carries
       across sweeps, so this change preserves correctness.
       ============================================================ */

    /* Column boundary conditions and initialization. */
    for (i = 1; i < _PB_N-1; i++) {
      v_[0][i] = SCALAR_VAL(1.0);
      /* p_[0][i] corresponds to original p[i][0] */
      p_[0][i] = SCALAR_VAL(0.0);
      q_[0][i] = v_[0][i]; /* = 1.0 */
    }

    /* Forward sweep (Thomas factorization) along j. */
    for (j = 1; j < _PB_N-1; j++) {
      /* For fixed j, iterations over i are independent; enable
         aggressive vectorization along i. */
#pragma GCC ivdep
      for (i = 1; i < _PB_N-1; i++) {
        DATA_TYPE denom = a * p_[j-1][i] + b;

        /* Use the shared denominator for both p and q updates,
           reducing one multiply-add per iteration while preserving
           floating-point semantics of the original formulation. */
        p_[j][i] = -c / denom;
        q_[j][i] =
          (-d * u_[j][i-1] +
           gd * u_[j][i]   -
           f  * u_[j][i+1] -
           a  * q_[j-1][i]) / denom;
      }
    }

    /* Bottom boundary for v. */
    for (i = 1; i < _PB_N-1; i++) {
      v_[_PB_N-1][i] = SCALAR_VAL(1.0);
    }

    /* Backward sweep (back substitution) along j. We keep j as the
       outer loop and iterate over i in the inner loop to maintain
       contiguous accesses to v, p, and q. */
    for (j = _PB_N-2; j >= 1; j--) {
#pragma GCC ivdep
      for (i = 1; i < _PB_N-1; i++) {
        v_[j][i] = p_[j][i] * v_[j+1][i] + q_[j][i];
      }
    }

    /* ============================================================
       Row sweep
       ------------------------------------------------------------
       Here the original loop order (i outer, j inner) already
       iterates along the contiguous j-dimension for all arrays
       u, v, p, and q. We therefore keep that order and only apply
       scalar-strength reduction (shared denominators and pre-
       computed ga = 1 + 2*a).
       ============================================================ */

    for (i = 1; i < _PB_N-1; i++) {
      u_[i][0] = SCALAR_VAL(1.0);
      p_[i][0] = SCALAR_VAL(0.0);
      q_[i][0] = u_[i][0];

      /* Forward sweep along j (Thomas factorization for each row i). */
      for (j = 1; j < _PB_N-1; j++) {
        DATA_TYPE denom = d * p_[i][j-1] + e;

        p_[i][j] = -f / denom;
        q_[i][j] =
          (-a * v_[i-1][j] +
           ga * v_[i][j]   -
           c  * v_[i+1][j] -
           d  * q_[i][j-1]) / denom;
      }

      /* Right boundary and backward substitution in j. */
      u_[i][_PB_N-1] = SCALAR_VAL(1.0);
      for (j = _PB_N-2; j >= 1; j--) {
        u_[i][j] = p_[i][j] * u_[i][j+1] + q_[i][j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
