       * 1) COLUMN SWEEP
       *    For each interior column index i, solve a 1D tridiagonal
       *    system along j, using u as the right-hand side and
       *    producing v.
       *    Each i-line is independent, so we parallelize/tilde over i.
       * ============================================================ */

#pragma omp for schedule(static)
      for (int ii = 1; ii < _PB_N-1; ii += tile_i)
      {
        const int i_max = (ii + tile_i < _PB_N-1) ? (ii + tile_i) : (_PB_N-1);

        for (i = ii; i < i_max; ++i)
        {
          const int im1 = i - 1;
          const int ip1 = i + 1;

          /* Row pointers for the current i-line of p and q. */
          DATA_TYPE * restrict p_i = p_[i];
          DATA_TYPE * restrict q_i = q_[i];

