          v_[0][i] = one;
          p_i[0]   = zero;
          q_i[0]   = one; /* equals v[0][i] */

          /* Forward sweep in j (Thomas factorization).
             Dependency is only along j (via p_i[j-1], q_i[j-1]). */
          for (j = 1; j < _PB_N-1; ++j)
          {
            const DATA_TYPE p_im1 = p_i[j-1];
            const DATA_TYPE denom = a * p_im1 + b;

            /* Read RHS stencil values from u once into registers. */
            const DATA_TYPE u_left   = u_[j][im1];
            const DATA_TYPE u_center = u_[j][i];
            const DATA_TYPE u_right  = u_[j][ip1];
