          }
        }
      }

      /* ============================================================
       * 2) ROW SWEEP
       *    For each interior row index i, solve a 1D tridiagonal
       *    system along j, using v as the right-hand side and
       *    producing the updated u.
       *    Again, i-lines are independent.
       * ============================================================ */

#pragma omp for schedule(static)
      for (int ii = 1; ii < _PB_N-1; ii += tile_i)
      {
        const int i_max = (ii + tile_i < _PB_N-1) ? (ii + tile_i) : (_PB_N-1);

        for (i = ii; i < i_max; ++i)
        {
          const int im1 = i - 1;
          const int ip1 = i + 1;

          DATA_TYPE * restrict p_i = p_[i];
          DATA_TYPE * restrict q_i = q_[i];

          /* Boundary conditions and forward-sweep seeds for this row. */
          u_[i][0] = one;
          p_i[0]   = zero;
          q_i[0]   = one; /* equals u[i][0] */

          /* Forward sweep in j (Thomas factorization along the row). */
          for (j = 1; j < _PB_N-1; ++j)
          {
            const DATA_TYPE p_im1 = p_i[j-1];
            const DATA_TYPE denom = d * p_im1 + e;

            const DATA_TYPE v_im1 = v_[im1][j];
            const DATA_TYPE v_i   = v_[i][j];
            const DATA_TYPE v_ip1 = v_[ip1][j];
            const DATA_TYPE q_im1 = q_i[j-1];

            p_i[j] = -f / denom;
