          ( -d * u_row[i-1]
            + alpha_col * u_row[i]
            - f * u_row[i+1]
            - a * q[i][j-1]
          ) * inv_denom;
      }
    }

    /* 3) Bottom boundary for backward substitution. */
    for (i = 1; i < _PB_N-1; i++) {
      v[_PB_N-1][i] = SCALAR_VAL(1.0);
    }

    /* 4) Backward substitution in j, logically from j = N-2 down to 1.
     *    We express this with a forward loop in jb to keep indices simple:
     *      j = _PB_N - 1 - jb  =>  j = N-2, N-3, ..., 1.
