    for (i = 1; i < _PB_N-1; i++) {
      for (j = 1; j < _PB_N-1; j++) {
        DATA_TYPE denom      = d * p[i][j-1] + e;
        DATA_TYPE inv_denom  = SCALAR_VAL(1.0) / denom;

        p[i][j] = -f * inv_denom;

